// Clean-room TSVC s118 profile; see package rights note.
#[no_mangle]
pub unsafe extern "C" fn tsvc_s118_triangular_convolution_recurrence(input:*const i64,length:usize,output:*mut u8,capacity:usize)->i64{if input.is_null()||length<8||length>74{return -1;}let v=core::slice::from_raw_parts(input,length);let nr=v[0];let passes=v[1];if !(2..=8).contains(&nr)||!(1..=4).contains(&passes){return -1;}let n=nr as usize;if length!=2+n+n*n{return -1;}let mut a=[0i64;8];let mut b=[0i64;64];for i in 0..n{let x=v[2+i];if !(-1..=1).contains(&x){return -1;}a[i]=x;}for i in 0..n*n{let x=v[2+n+i];if !(-1..=1).contains(&x){return -1;}b[i]=x;}if output.is_null()||capacity<8*n{return -2;}for _ in 0..passes{for i in 1..n{for j in 0..i{a[i]+=b[j*n+i]*a[i-j-1];}}}for i in 0..n{let bits=a[i] as u64;for j in 0..8{output.add(8*i+j).write((bits>>(8*j))as u8);}}n as i64}
